-- Generated offline by scripts/import-legacy-archive.mjs. Execute as DB administrator.
-- Transactional; reruns skip previously imported identities, including edited/archived items.
begin;
lock table public.archive_items, public.archive_revisions in share row exclusive mode;
create temporary table legacy_archive_import (id uuid primary key, kind text not null, slug text not null, content jsonb not null, unique(kind, slug)) on commit drop;
do $legacy$
declare r record;
begin
 for r in select * from legacy_archive_import loop
  if not public.archives_validate_content(r.content) then raise exception 'Invalid content for %: %', r.kind, r.slug; end if;
  if exists (select 1 from public.archive_items i where i.id = r.id) then
   if not exists (select 1 from public.archive_items i join public.archive_revisions rev on rev.item_id = i.id where i.id = r.id and i.kind = r.kind and rev.version = 1 and rev.action = 'publish' and rev.actor_email = 'legacy-import' and rev.kind = r.kind and rev.slug = r.slug) then
    raise exception 'Legacy ID collision: % %', r.kind, r.slug;
   end if;
  else
   if exists (select 1 from public.archive_items i where i.kind = r.kind and (i.slug = r.slug or i.draft->>'slug' = r.slug or i.published->>'slug' = r.slug)) then
    raise exception 'Legacy slug collision: % %', r.kind, r.slug;
   end if;
  end if;
 end loop;
end $legacy$;
commit;
